// STAGE 1 - three focused Tavily Research tasks. Each digs deep in its own
// slice; duplicates are merged later, so overlap is harmless.
const cfg = $input.first().json;
const days = Number(cfg.days_back) || 30;
const start = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);

const COMMON =
  ` between ${start} and today. ` +
  `For every transaction give: announcement date (YYYY-MM-DD), asset name, transaction type, one-sentence ` +
  `description, buyer, seller, other parties, deal value exactly as stated, buyer's legal advisor, seller's ` +
  `legal advisor, other legal advisors, status, sector (office/retail/logistics-industrial/residential/land/hotel), ` +
  `and the source URLs. STRICT RULE: report only facts stated explicitly in the sources; leave a field empty ` +
  `if the sources do not state it; every transaction MUST have at least one source URL. ` +
  `Exclude lease deals, market reports and transactions outside Poland.`;

const FOCUSES = [
  `List ALL sales and acquisitions of real estate announced in Poland: office buildings, shopping centres and ` +
  `retail parks, logistics and warehouse assets or portfolios, residential/PRS portfolios, land plots and hotels. ` +
  `Prioritise Polish and CEE trade press (eurobuildcee.com, property-forum.eu, propertynews.pl).` + COMMON,

  `List ALL real estate FINANCING and REFINANCING transactions and real estate joint ventures announced in ` +
  `Poland: secured loans, portfolio financings, refinancings of buildings or portfolios, forward funding deals ` +
  `and JV platforms. Include the lender banks as other parties.` + COMMON,

  `List ALL real estate transactions in Poland announced on the websites and news sections of these law firms: ` +
  `dentons.com, cms.law, gtlaw.com, wolftheiss.com, bakermckenzie.com, cliffordchance.com, rzmlaw.com (Rymarz ` +
  `Zdort Maruta), dzp.pl (Domanski Zakrzewski Palinka), whitecase.com, dlapiper.com, gide.com, pinsentmasons.com. ` +
  `These announcements always name the legal advisors - capture them precisely.` + COMMON,
];

// Tavily output_schema rules: ROOT may contain ONLY 'properties'/'required';
// EVERY property MUST have a 'description'.
const output_schema = JSON.stringify({
  properties: {
    transactions: {
      type: 'array',
      description: 'List of individual real estate transactions announced in Poland within the requested time window. One entry per transaction.',
      items: {
        type: 'object',
        description: 'A single real estate transaction in Poland.',
        properties: {
          announcement_date: { type: 'string', description: 'Date the transaction was announced, YYYY-MM-DD. Empty string if the sources do not state it.' },
          deal_asset: { type: 'string', description: 'Name of the asset or portfolio (e.g. "P180 office building, Warsaw").' },
          transaction_type: { type: 'string', description: 'One of: sale, acquisition, financing, JV. Empty string if unclear.' },
          description: { type: 'string', description: 'One-sentence factual description paraphrased from the sources.' },
          buyer: { type: 'string', description: 'Buyer / investor. Empty string if not stated.' },
          seller: { type: 'string', description: 'Seller / vendor. Empty string if not stated.' },
          other_parties: { type: 'string', description: 'Other parties involved (lenders, JV partners, agents). Empty string if none stated.' },
          deal_value: { type: 'string', description: 'Deal value copied exactly as written (e.g. "EUR 100 million"). Empty string if not disclosed.' },
          buyer_legal_advisor: { type: 'string', description: 'Law firm advising the buyer. Empty string if not stated.' },
          seller_legal_advisor: { type: 'string', description: 'Law firm advising the seller. Empty string if not stated.' },
          other_legal_advisors: { type: 'string', description: 'Other legal advisors involved. Empty string if none stated.' },
          status: { type: 'string', description: 'One of: completed, signed, announced. Empty string if unclear.' },
          sector: { type: 'string', description: 'One of: office, retail, logistics-industrial, residential, land, hotel, not identified. Judge by the asset itself.' },
          source_urls: { type: 'array', description: 'Direct URLs of articles or announcements describing THIS transaction. At least one URL is mandatory.', items: { type: 'string', description: 'A single source URL.' } },
        },
        required: ['deal_asset', 'source_urls'],
      },
    },
  },
  required: ['transactions'],
});

return FOCUSES.map((research_input) => ({ json: {
  research_input,
  output_schema,
  model: String(cfg.research_model || 'pro'),
} }));

// The loop spins as ONE batch: items leave only when EVERY research task
// is finished, so downstream nodes execute exactly once. Progress counters
// and research labels feed the SSE heartbeat (phase_id research_1..3).
const LABELS = ['sprzedaże i przejęcia', 'finansowania i JV', 'kancelarie prawne']; // order = FOCUSES
const items = $input.all();
const done = (s) => s === 'completed' || s === 'failed';
const completed = items.filter((i) => done(i.json.status)).length;
const allDone = items.length > 0 && completed === items.length;
const doneLabels = items.map((i, idx) => (done(i.json.status) ? LABELS[idx] : null)).filter(Boolean).join(', ');
return items.map((i, idx) => ({ json: { ...i.json, research_label: LABELS[idx] || '', done_labels: doneLabels, all_done: allDone, completed_count: completed, total_count: items.length } }));

// Parses the structured content of all research passes, enforces the time
// window, drops source-less deals (zero-hallucination rule) and merges
// duplicates found by different passes into single deals.
const cfg = $('⚙️ Config').first().json;
const cutoff = new Date(Date.now() - (Number(cfg.days_back) || 30) * 24 * 60 * 60 * 1000);
const norm = (s) => String(s ?? '').toLowerCase().replace(/\s+/g, ' ').trim();

const raw = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.status && j.status !== 'completed') continue;
  let content = j.content;
  if (typeof content === 'string') { try { content = JSON.parse(content); } catch { continue; } }
  for (const t of (content && content.transactions) || []) {
    const urls = (t.source_urls || []).map((u) => String(u).trim()).filter(Boolean);
    if (urls.length === 0) continue;               // no source, no row
    if (!norm(t.deal_asset)) continue;             // unnamed deal is unverifiable
    let announced = '';
    if (t.announcement_date) {
      const d = new Date(t.announcement_date);
      if (!isNaN(d.getTime())) {
        if (d < cutoff) continue;                  // outside the window
        announced = d.toISOString().slice(0, 10);
      }
    }
    raw.push({ ...t, announcement_date: announced, urls });
  }
}

// Merge duplicates across passes: same asset (containment match) + compatible buyer.
const groups = [];
const tokens = (s) => norm(s).split(/[^a-z0-9\u00e0-\u017f]+/).filter((w) => w.length >= 4);
const sameDeal = (a, b) => {
  const ta = norm(a.deal_asset), tb = norm(b.deal_asset);
  const assetMatch = ta === tb ||
    (ta.length > 6 && tb.length > 6 && (ta.includes(tb) || tb.includes(ta))) ||
    (tokens(ta).filter((w) => tokens(tb).includes(w)).length >= 2);
  if (!assetMatch) return false;
  const ba = norm(a.buyer), bb = norm(b.buyer);
  if (!ba || !bb) return true;
  return ba.includes(bb) || bb.includes(ba);
};

const FIELDS = ['announcement_date','deal_asset','transaction_type','description','buyer','seller',
  'other_parties','deal_value','buyer_legal_advisor','seller_legal_advisor','other_legal_advisors',
  'status','sector'];

for (const t of raw) {
  let g = groups.find((x) => sameDeal(x, t));
  if (!g) { g = { ...Object.fromEntries(FIELDS.map((f) => [f, ''])), urls: [] }; groups.push(g); }
  for (const f of FIELDS) {
    const v = String(t[f] || '').trim();
    if (!v || v === 'not identified') continue;
    if (!g[f]) g[f] = v;
    else if (f === 'announcement_date' && v < g[f]) g[f] = v;  // earliest date wins
  }
  for (const u of t.urls) if (!g.urls.includes(u)) g.urls.push(u);
}

console.log(`Discovery: ${raw.length} raw entries -> ${groups.length} unique deals`);
if (groups.length === 0) {
  // Nothing found: keep one placeholder item flowing so the stream still ends
  // with an (empty) final table instead of dying mid-flight.
  return [{ json: { deal_id: -1, _empty: true, deals_total: 0, ...Object.fromEntries(FIELDS.map((f) => [f, ''])), sources: '' } }];
}
return groups.map((g, idx) => ({ json: {
  deal_id: idx,
  ...Object.fromEntries(FIELDS.map((f) => [f, g[f]])),
  sector: g.sector || 'not identified',
  sources: g.urls.join('; '),
  deals_total: groups.length,
} }));

// Flags deals worth a deepening pass: anything with a data gap the client
// cares about (advisors, seller, value, date), capped by deepen_limit.
// deepen_idx numbers the flagged deals 1..N for the per-deal progress events.
const cfg = $('⚙️ Config').first().json;
const enabled = cfg.enable_deepening === true || String(cfg.enable_deepening) === 'true';
const limit = Number(cfg.deepen_limit) || 15;

let used = 0;
const out = $input.all().map((item) => {
  const r = item.json;
  if (r._empty) return { json: { ...r, needs_deepen: false, gaps: '' } };
  const gaps = [];
  if (!r.buyer_legal_advisor) gaps.push('buyer_legal_advisor');
  if (!r.seller_legal_advisor) gaps.push('seller_legal_advisor');
  if (!r.seller) gaps.push('seller');
  if (!r.deal_value) gaps.push('deal_value');
  if (!r.announcement_date) gaps.push('announcement_date');
  if (!r.other_parties) gaps.push('other_parties');
  const needs_deepen = enabled && gaps.length > 0 && used < limit;
  if (needs_deepen) used++;
  return { json: { ...r, needs_deepen, deepen_idx: needs_deepen ? used : 0, gaps: gaps.join(', ') } };
});
const deepenTotal = out.filter((o) => o.json.needs_deepen).length;
return out.map((o) => ({ json: { ...o.json, deepen_total: deepenTotal } }));

// Turns the LLM query plan for the CURRENT deal (one loop iteration = one
// deal) into search items. Law-firm-only queries get include_domains.
const cfg = $('⚙️ Config').first().json;
const maxQ = Number(cfg.max_queries_per_deal) || 3;
const LAW_DOMAINS = ['dentons.com','cms.law','gtlaw.com','wolftheiss.com','bakermckenzie.com',
  'cliffordchance.com','rzmlaw.com','dzp.pl','whitecase.com','dlapiper.com','gide.com','pinsentmasons.com'];

const deal = $('SSE · Deal progress').first().json;
const plan = $input.first().json;
const rawText = [plan.text, plan.output, plan.response].find((v) => typeof v === 'string') || '';
let data = null;
try {
  data = JSON.parse(rawText.replace(/^\s*```(json)?/i, '').replace(/```\s*$/, '').trim());
} catch (e) { data = null; }
let queries = (data && Array.isArray(data.queries)) ? data.queries : [];
// Fallback if the model returned garbage - deterministic queries, never zero.
if (queries.length === 0) {
  queries = [
    { query: [deal.deal_asset, deal.buyer, 'transaction'].filter(Boolean).join(' '), law_firms_only: false },
    { query: [deal.deal_asset, 'advised legal advisor'].filter(Boolean).join(' '), law_firms_only: true },
  ];
}
const out = [];
for (const q of queries.slice(0, maxQ)) {
  const query = String(q.query || '').trim().slice(0, 390);
  if (!query) continue;
  out.push({ json: {
    deal_id: deal.deal_id,
    query,
    include_domains: q.law_firms_only ? LAW_DOMAINS : [],
    sources: deal.sources,
  } });
}
// Never return zero items - the loop iteration must keep flowing.
if (out.length === 0) {
  out.push({ json: { deal_id: deal.deal_id, query: String(deal.deal_asset).slice(0, 390), include_domains: [], sources: deal.sources } });
}
return out;

// From this deal's follow-up searches take up to max_links_per_query NEW
// URLs each (skipping ones already in Sources), deduped. Always returns at
// least one item (a _skip marker) so the loop iteration never stalls.
const cfg = $('⚙️ Config').first().json;
const maxLinks = Number(cfg.max_links_per_query) || 2;

const deal = $('SSE · Deal progress').first().json;
const responses = $input.all();
const existing = String(deal.sources || '').toLowerCase();
const seen = new Set();
const out = [];

for (let i = 0; i < responses.length; i++) {
  let taken = 0;
  for (const r of responses[i].json.results || []) {
    if (taken >= maxLinks) break;
    const url = r.url || '';
    if (!url || /\.pdf(\?|$)/i.test(url)) continue;
    const key = url.replace(/\/+$/, '').toLowerCase();
    if (existing.includes(key) || seen.has(key)) continue;
    out.push({ json: { deal_id: deal.deal_id, url } });
    seen.add(key);
    taken++;
  }
}
if (out.length === 0) return [{ json: { deal_id: deal.deal_id, _skip: true } }];
return out.map((o) => ({ json: { ...o.json, fetch_total: out.length } }));

// Builds the enrichment LLM input: deal context + one article's text each.
// Always returns >=1 item so the loop iteration never stalls; the fallback
// item makes the LLM answer same_transaction=false and contributes nothing.
const deal = $('SSE · Deal progress').first().json;
const links = $('Select new sources').all();
const extracts = $input.all();

const cleanText = (raw) => String(raw || '')
  .split('\n')
  .filter((l) => { const t = l.trim(); return !t.startsWith('![') && !/^\[[^\]]*\]\([^)]*\)$/.test(t); })
  .join('\n').replace(/\s+/g, ' ').trim();

const out = [];
for (let i = 0; i < extracts.length; i++) {
  const link = (links[i] || {}).json || {};
  const results = extracts[i].json.results || [];
  const body = cleanText(results[0] ? results[0].raw_content : '').slice(0, 8000);
  if (!body) continue;
  const ctx = {
    deal_asset: deal.deal_asset, buyer: deal.buyer, seller: deal.seller,
    deal_value: deal.deal_value, missing_fields: deal.gaps,
  };
  out.push({ json: {
    deal_id: deal.deal_id, url: link.url,
    llm_input: 'DEAL: ' + JSON.stringify(ctx) + '\nARTICLE: ' + body,
  } });
}
if (out.length === 0) {
  out.push({ json: { deal_id: deal.deal_id, url: '', llm_input: 'DEAL: {}\nARTICLE: (no article content available)' } });
}
return out;

// Aggregates this iteration's enrichment into ONE item and always returns
// it, so the loop continues even when nothing was found for this deal.
// Runs on both paths (with and without new sources).
const deal = $('SSE · Deal progress').first().json;

const FIELDS = ['announcement_date','transaction_type','description','buyer','seller','other_parties',
  'deal_value','buyer_legal_advisor','seller_legal_advisor','other_legal_advisors','status','sector'];

const f = { urls: [] };
let inputs = [], outputs = [];
try { inputs = $('Prepare enrich input').all(); } catch (e) {}
try { outputs = $('LLM · Enrich deal').all(); } catch (e) {}

for (let i = 0; i < outputs.length; i++) {
  const src = (inputs[i] || {}).json || {};
  if (src.deal_id !== deal.deal_id) continue; // stale items from a previous iteration
  const rawText = [outputs[i].json.text, outputs[i].json.output, outputs[i].json.response]
    .find((v) => typeof v === 'string') || '';
  let data = null;
  try { data = JSON.parse(rawText.replace(/^\s*```(json)?/i, '').replace(/```\s*$/, '').trim()); } catch (e) { continue; }
  if (!data || data.same_transaction !== true) continue; // article about another deal
  let contributed = false;
  for (const field of FIELDS) {
    const v = data[field];
    if (v && typeof v === 'string' && !f[field]) { f[field] = v.trim(); contributed = true; }
  }
  if (contributed && src.url && !f.urls.includes(src.url)) f.urls.push(src.url);
}

return [{ json: { deal_id: deal.deal_id, fill: f } }];

// Final assembly: deals from discovery + per-deal enrichment fills from the
// loop. Fill ONLY empty fields; append contributing URLs to Sources.
// Column names exactly as the frontend table expects (COLUMNS[].apiKey).
const base = $('Mark for deepening').all().map((i) => i.json).filter((r) => !r._empty);

// Fills arrive through Gather branches as items shaped { deal_id, fill }.
const fills = new Map();
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.fill) fills.set(j.deal_id, j.fill);
}

// Frontend sorts 'Data ogłoszenia' as D.MM.YYYY (like the mock) - convert ISO dates.
const plDate = (iso) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ''));
  return m ? `${Number(m[3])}.${m[2]}.${m[1]}` : String(iso || '');
};

const rows = base.map((r) => {
  const f = fills.get(r.deal_id) || { urls: [] };
  const val = (field) => r[field] || f[field] || '';
  const sources = [r.sources, ...(f.urls || [])].filter(Boolean).join('; ');
  return {
    'Data ogłoszenia': plDate(val('announcement_date')),
    'Deal/asset': r.deal_asset || '',
    'Rodzaj transakcji': val('transaction_type'),
    'Opis transakcji': val('description'),
    'Buyer / inwestor': val('buyer'),
    'Seller / vendor': val('seller'),
    'Other parties involved': val('other_parties'),
    'Deal value': val('deal_value'),
    'Buyer legal advisor': val('buyer_legal_advisor'),
    'Seller legal advisor': val('seller_legal_advisor'),
    'Other legal advisors involved': val('other_legal_advisors'),
    'Status transakcji': val('status'),
    'Sektor': val('sector') || 'not identified',
    'Źródła informacji': sources,
  };
});

// Single item with the whole table -> the final Respond node streams it
// as one plain JSON array chunk (exactly the framing the mock used).
return [{ json: { transactions: rows } }];
